import pandas as pd


def run(inputs: dict) -> dict:
    target_snapshot = inputs["target_snapshot"].copy()
    cdc_events = inputs["cdc_events"].copy()
    watermark = inputs["watermark"].copy()

    # Determine the watermark high_ts (assume single row/value)
    if len(watermark) == 0:
        high_ts = None
    else:
        high_ts = watermark["high_ts"].iloc[0]

    # Filter events strictly after the watermark
    if high_ts is None:
        events = cdc_events.copy()
    else:
        events = cdc_events[cdc_events["event_ts"] > high_ts].copy()

    # Apply events sequentially in (event_ts, event_seq) order
    events = events.sort_values(["event_ts", "event_seq"], kind="mergesort")

    # Build initial state from target_snapshot
    state = {}
    col_order = list(target_snapshot.columns)
    for _, row in target_snapshot.iterrows():
        uid = row["user_id"]
        state[uid] = {
            "email": row["email"],
            "status": row["status"],
            "status_ts": row["status_ts"],
        }

    seven_days = pd.Timedelta(days=7)

    for _, ev in events.iterrows():
        uid = ev["user_id"]
        op = ev["op"]
        ts = ev["event_ts"]
        email = ev["email"]

        cur = state.get(uid)

        if op == "D":
            if cur is None:
                # New user directly deleted: no prior email to preserve,
                # use the email carried on the delete event.
                state[uid] = {
                    "email": email,
                    "status": "DELETED",
                    "status_ts": ts,
                }
            else:
                # Soft delete: email preserved as of deletion.
                state[uid] = {
                    "email": cur["email"],
                    "status": "DELETED",
                    "status_ts": ts,
                }
        elif op == "U":
            if cur is None or cur["status"] == "ACTIVE":
                state[uid] = {
                    "email": email,
                    "status": "ACTIVE",
                    "status_ts": ts,
                }
            else:
                # cur['status'] == 'DELETED'
                prev_del_ts = cur["status_ts"]
                if ts > (prev_del_ts + seven_days):
                    # Resurrection allowed: strictly more than 7 days later.
                    state[uid] = {
                        "email": email,
                        "status": "ACTIVE",
                        "status_ts": ts,
                    }
                # else: discard the update, deletion remains sticky.
        # Unknown ops are ignored (not part of legacy semantics).

    # Build result preserving original column order, appending any new users
    # in the order they first appeared in the event stream processing above.
    rows = []
    for uid, v in state.items():
        rows.append(
            {
                "user_id": uid,
                "email": v["email"],
                "status": v["status"],
                "status_ts": v["status_ts"],
            }
        )

    new_snapshot = pd.DataFrame(rows, columns=["user_id", "email", "status", "status_ts"])

    # Align column order with target_snapshot if it had the same columns.
    if set(col_order) == set(new_snapshot.columns):
        new_snapshot = new_snapshot[col_order]

    return {"new_snapshot": new_snapshot}
